// ***************
// Filename: py_sysctl_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of py_sysctl: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to py_sysctl's logic on named ports, its
//   status comes back on input ports. py_soc system control: reset cause,
//   boot status, cycle counter, SoC ID, core logic reset, clock enables.
//   Generated by ip/scripts/regmap_gen.py from py_sysctl_regs.json: edit the
//   JSON and regenerate (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "SCTL" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 RESET_CAUSE CMD  cause of the last reset (sticky across system
//                       resets, cleared by the external reset only); write 1
//                       to clear
//                       [0] EXTERNAL: external reset (rst_n)
//                       [1] WATCHDOG: watchdog reset
//     0x14 BOOT_STATUS RO   boot loader result
//                       [0] DONE: boot done
//                       [1] ERROR: boot error
//                       [6:4] CODE: boot error code
//     0x18 CYCLES      RO   free-running clock counter (wraps at 2**32)
//     0x1C SOC_ID      RO   SoC ID 0x50590100 ("PY", version 1.0)
//     0x20 CORE_RESET  RW   1 = release the reset of the logic outside py_soc
//                       (cleared by every system reset), reset 0x0
//     0x24 CLK_EN      RW   clock generator output enables, reset
//                       CLK_EN_RST[NCLK-1:0]
//     0x28 CLK_STATUS  RO   clock generator status
//                       [0] LOCKED: outputs locked (1 without a clock
//                         generator)
//                       [1] PRESENT: clock generator present
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-16
module py_sysctl_regs #(
  parameter int NCLK = 1,  // clock generator outputs (1..32)
  parameter logic [31:0] CLK_EN_RST = 32'hFFFF_FFFF  // CLK_EN reset value
) (
  input  logic            aclk,             // clock
  input  logic            aresetn,          // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // r: py_sysctl_regs_if.regs (src/include/py_sysctl_regs_if.sv) {reset_cause_i=sts_reset_cause reset_cause_o=cfg_reset_cause reset_cause_wr_o=cfg_reset_cause_wr boot_status_i=sts_boot_status cycles_i=sts_cycles soc_id_i=sts_soc_id core_reset_o=cfg_core_reset core_reset_wr_o=cfg_core_reset_wr clk_en_o=cfg_clk_en clk_en_wr_o=cfg_clk_en_wr clk_status_i=sts_clk_status}
  py_sysctl_regs_if.regs r
);
  // register signals, joined to the interface r
  logic [2-1:0] reset_cause_i;
  logic [2-1:0] reset_cause_o;
  logic reset_cause_wr_o;
  logic [32-1:0] boot_status_i;
  logic [32-1:0] cycles_i;
  logic [32-1:0] soc_id_i;
  logic core_reset_o;
  logic core_reset_wr_o;
  logic [NCLK-1:0] clk_en_o;
  logic clk_en_wr_o;
  logic [2-1:0] clk_status_i;
  assign reset_cause_i = r.sts_reset_cause;
  assign r.cfg_reset_cause = reset_cause_o;
  assign r.cfg_reset_cause_wr = reset_cause_wr_o;
  assign boot_status_i = r.sts_boot_status;
  assign cycles_i = r.sts_cycles;
  assign soc_id_i = r.sts_soc_id;
  assign r.cfg_core_reset = core_reset_o;
  assign r.cfg_core_reset_wr = core_reset_wr_o;
  assign r.cfg_clk_en = clk_en_o;
  assign r.cfg_clk_en_wr = clk_en_wr_o;
  assign clk_status_i = r.sts_clk_status;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "SCTL";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_RESET_CAUSE = 8'h10;
  localparam logic [7:0] A_BOOT_STATUS = 8'h14;
  localparam logic [7:0] A_CYCLES = 8'h18;
  localparam logic [7:0] A_SOC_ID = 8'h1C;
  localparam logic [7:0] A_CORE_RESET = 8'h20;
  localparam logic [7:0] A_CLK_EN = 8'h24;
  localparam logic [7:0] A_CLK_STATUS = 8'h28;
  localparam int MAP_WORDS = 11;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(8)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] reset_cause_q;
  logic [31:0] core_reset_q;
  logic [31:0] clk_en_q;
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      reset_cause_q <= '0;
      reset_cause_wr_o <= 1'b0;
      core_reset_q <= 32'h0;
      core_reset_wr_o <= 1'b0;
      clk_en_q <= 32'(CLK_EN_RST[NCLK-1:0]);
      clk_en_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_BOOT_STATUS || wa == A_CYCLES || wa == A_SOC_ID || wa == A_CLK_STATUS);   // writes to read-only words: SLVERR
      begin
        reset_cause_wr_o <= wr_en && wa == A_RESET_CAUSE;
        if (wr_en && wa == A_RESET_CAUSE) reset_cause_q <= (reset_cause_q & ~wmask) | (wr_data & wmask);
      end
      begin
        core_reset_wr_o <= wr_en && wa == A_CORE_RESET;
        if (wr_en && wa == A_CORE_RESET) core_reset_q <= (core_reset_q & ~wmask) | (wr_data & wmask);
      end
      begin
        clk_en_wr_o <= wr_en && wa == A_CLK_EN;
        if (wr_en && wa == A_CLK_EN) clk_en_q <= (clk_en_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign reset_cause_o = reset_cause_q[2-1:0];
  assign core_reset_o = core_reset_q[1-1:0];
  assign clk_en_o = clk_en_q[NCLK-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_RESET_CAUSE: rd_data = 32'(reset_cause_i);
      A_BOOT_STATUS: rd_data = 32'(boot_status_i);
      A_CYCLES: rd_data = 32'(cycles_i);
      A_SOC_ID: rd_data = 32'(soc_id_i);
      A_CORE_RESET: rd_data = core_reset_q;
      A_CLK_EN: rd_data = clk_en_q;
      A_CLK_STATUS: rd_data = 32'(clk_status_i);
      default: begin
      end
    endcase
  end
endmodule
